// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint128 amount) public {
        vm.assume(actor != address(0) && uint256(amount) > 0);
        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        c.addToBalance{value: uint256(amount)}();
        assertEq(c.getBalance(actor) + c.getBalance(address(0)), address(c).balance, "invariant: contract balance equals sum of user balances");
    }
}
